def vowelConsonantScore(s):
    v = 0  # number of vowels
    c = 0  # number of consonants
    for ch in s:
        # Only lowercase letters count; spaces and digits are skipped
        if 'a' <= ch <= 'z':
            if ch in "aeiou":
                v += 1
            else:
                c += 1
    # Avoid division by zero when there are no consonants
    if c == 0:
        return 0
    # Floor division gives the required rounded-down quotient
    return v // c
